// CSharpParserInit initializes any static state used to implement CSharpParser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewCSharpParser(). You can call this function if you wish to initialize the static state ahead
// of time.
func CSharpParserInit() {
	staticData := &CSharpParserParserStaticData
	staticData.once.Do(csharpparserParserInit)
}

// NewCSharpParser produces a new parser instance for the optional input antlr.TokenStream.
func NewCSharpParser(input antlr.TokenStream) *CSharpParser {
	CSharpParserInit()
	this := new(CSharpParser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &CSharpParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "CSharpParser.g4"

	return this
}

